//! Compiling a stored wiring document into the graph the router walks.
//!
//! The catalog owns the authored document (`catalog.wirings.graph_json`); the
//! router owns the indexed graph. Neither depends on the other, and this is the
//! seam that keeps it that way: the host is the process that reads the store, so
//! the translation belongs where the read already is (`wamn_router` crate docs —
//! "the store read that resolves a wiring is the host's"). What the router
//! receives is therefore always a document that
//! [`WiringDocument::parse`](wamn_catalog::WiringDocument::parse) already
//! validated.
//!
//! Two authored fields deliberately do not cross: a node's `interface-version`,
//! which is late binding's business and not the walk's, and an edge's
//! `to-port`, which the router has no field for because it routes by the
//! emitting node's port alone.

use serde_json::Value;
use wamn_catalog::{WiringDocument, WiringTerminal};
use wamn_router::{Terminal, Wiring, WiringEdge, WiringError, WiringNode};

/// Index one stored wiring document into the graph a delivery is walked over.
pub fn compile_wiring(document: &WiringDocument) -> Result<Wiring, WiringError> {
    let nodes = document
        .nodes
        .iter()
        .map(|(id, node)| WiringNode {
            id: id.clone(),
            component: node.component.clone(),
            operation: node.operation.clone(),
            // The router reads only the reserved `retry` object and
            // `deadline-ms` out of this; the rest is the component's own.
            config: Value::Object(node.params.clone().into_iter().collect()),
            // Connections are bound per environment by the host, not authored
            // into the graph — the document has no connection field.
            connection: None,
            terminal: node.terminal.map(terminal),
        })
        .collect();
    let edges = document
        .edges
        .iter()
        .map(|edge| WiringEdge {
            from: edge.from.clone(),
            from_port: edge.from_port.clone(),
            to: edge.to.clone(),
            // The document carries fan-out order as array position within a
            // `(from, from-port)` group, and the router's sort is stable, so
            // position IS the ordinal. A second encoding of the same order could
            // disagree with it.
            ordinal: None,
        })
        .collect();
    Wiring::compile(document.entry.clone(), nodes, edges)
}

/// The authored terminal as the router's own. Total, and it must stay total:
/// a variant added on either side without the other is a compile error here,
/// which is the point of translating in one place.
fn terminal(declared: WiringTerminal) -> Terminal {
    match declared {
        WiringTerminal::Respond => Terminal::Respond,
        WiringTerminal::Emit => Terminal::Emit,
    }
}
--------------------------------------------------------------------------------

